preConditionHook:
// A sharp countertrend bear spike -- spikeBars consecutive bear TREND bars,
// each with a body of at least bodyFraction of its own range -- reaches down
// to the moving average, and the current bar closes up: buy near its close.
// Short is the mirror.
//
// The run is read at bars 1..spikeBars, NOT 0..spikeBars-1: the current bar
// is the reversal bar and closes against the spike, so it cannot be part of
// it. The run test is StrongTrendBarRun's, written the same way -- start true
// and let any failing bar clear the flag, so the loop runs unconditionally
// and EasyLanguage's lack of short-circuiting cannot matter.
//
// "Reaches the average" is a BAND, low at or below the EMA plus supportAtr
// ATRs, not a touch: the source's tolerance is in ticks and the engine
// exposes no tick size, so it becomes an ATR fraction as in
// PriorSessionLevelTest and BreakoutLevelRetest.
//
// MultiWalk's WFSafe_Xaverage, which the EasyLanguage twin calls. MEASURED
// bit-identical to the plain XAverage built-in AT A FIXED LENGTH ((wf - xa)
// printed exactly 0 on all 17,785 probed bars). SEED: the PRICE on the
// study's first calculated bar, NOT a length-term simple average -- an EMA
// never forgets its seed, so the seed BAR is part of the specification and
// moves with Max Bars Back and the chart start. ONE STATEMENT, IN EL'S FORM:
// x + sf*(p - x), never sf*p + (1-sf)*x -- the two separate on 67% of bars
// past 100. NO WARM-UP HOLE: non-zero from bar 1 on, so no CurrentBar guard
// returning 0. UNMEASURED: the walkforward LENGTH CHANGE, so emaLength is
// PINNED in the grid; and the lagged read XAverage(...)[k], which this rule
// does not use -- it reads the current value only.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
emaSf = 2.0 / (emaLength + 1.0);
if (ctx.CurrentBar() == 1) {
    emaVal = close[0];
} else {
    emaVal = emaVal + emaSf * (close[0] - emaVal);
}
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, with the measurements). Seeded with a full
// sum on the first calculated bar or when the length changes, then updated as
// TWO statements -- EL evaluates S[1] + in - out left to right, and folding
// it to S += in - out rounds differently.
if (atrLen != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrVal = atrSum / (int)atrLookback;
bearRun = true;
bullRun = true;
for (int k = 1; k <= (int)spikeBars; ++k) {
    if (el_ge(close[k], open[k])) bearRun = false;
    if (el_lt(open[k] - close[k], bodyFraction * (high[k] - low[k]))) bearRun = false;
    if (el_le(close[k], open[k])) bullRun = false;
    if (el_lt(close[k] - open[k], bodyFraction * (high[k] - low[k]))) bullRun = false;
}
buyNow = bearRun && el_le(low[0], emaVal + supportAtr * atrVal) && el_gt(close[0], open[0]);
sellNow = bullRun && el_ge(high[0], emaVal - supportAtr * atrVal) && el_lt(close[0], open[0]);
